#include "MainView.h"

namespace
{
juce::var makeObject(){return juce::var(new juce::DynamicObject());}
float getFloat(juce::DynamicObject*o,const char*k,float f){const juce::Identifier id(k);return(o&&o->hasProperty(id))?(float)(double)o->getProperty(id):f;}
int getInt(juce::DynamicObject*o,const char*k,int f){const juce::Identifier id(k);return(o&&o->hasProperty(id))?(int)o->getProperty(id):f;}
bool getBool(juce::DynamicObject*o,const char*k,bool f){const juce::Identifier id(k);return(o&&o->hasProperty(id))?(bool)o->getProperty(id):f;}
}

MainView::MainView(AudioEngine& engine)
    : audioEngine(engine), ampPage(engine.getAmpEngine()), pedalPage(engine.getHQEffectsRack()),
      cabPage(engine.getCabMicEngine()), effectsPage(engine.getHQEffectsRack()),
      performancePage(engine), settingsPage(engine.getDeviceManager())
{
    addAndMakeVisible(navigation);addAndMakeVisible(ampPage);addChildComponent(pedalPage);addChildComponent(cabPage);addChildComponent(effectsPage);addChildComponent(performancePage);addChildComponent(settingsPage);
    navigation.onPageSelected=[this](NavigationBar::Page p){showPage(p);};
    auto gain=[](juce::Slider&s,double lo,double hi,double v){s.setSliderStyle(juce::Slider::LinearHorizontal);s.setTextBoxStyle(juce::Slider::TextBoxRight,false,64,24);s.setRange(lo,hi,.1);s.setValue(v,juce::dontSendNotification);s.setNumDecimalPlacesToDisplay(1);s.setTextValueSuffix(" dB");};
    gain(inputGainSlider,-36,18,-6);gain(outputGainSlider,-60,6,-18);
    ampModeSelector.addItem("LEGACY 20",1);ampModeSelector.addItem("HQ 20",2);ampModeSelector.setSelectedId(1,juce::dontSendNotification);
    inputLabel.setText("INPUT",juce::dontSendNotification);outputLabel.setText("OUTPUT",juce::dontSendNotification);inputMeterLabel.setText("-100 dB",juce::dontSendNotification);outputMeterLabel.setText("-100 dB",juce::dontSendNotification);
    for(auto*l:{&inputLabel,&outputLabel})l->setColour(juce::Label::textColourId,juce::Colour::fromRGB(165,174,184));for(auto*l:{&inputMeterLabel,&outputMeterLabel})l->setColour(juce::Label::textColourId,juce::Colour::fromRGB(98,213,167));
    for(auto*c:{(juce::Component*)&inputGainSlider,&outputGainSlider,&ampModeSelector,&bypassButton,&inputLabel,&outputLabel,&inputMeterLabel,&outputMeterLabel})addAndMakeVisible(c);
    presetLabel.setText("PRESET",juce::dontSendNotification);presetLabel.setColour(juce::Label::textColourId,juce::Colour::fromRGB(222,110,58));presetLabel.setFont(juce::Font(12.0f,juce::Font::bold));presetSelector.setEditableText(true);presetSelector.setTextWhenNothingSelected("Type preset name");
    for(auto*c:{(juce::Component*)&presetLabel,&presetSelector,&presetSaveButton,&presetDeleteButton})addAndMakeVisible(c);
    inputGainSlider.onValueChange=[this]{audioEngine.setInputGainDb((float)inputGainSlider.getValue());};outputGainSlider.onValueChange=[this]{audioEngine.setOutputGainDb((float)outputGainSlider.getValue());};
    ampModeSelector.onChange=[this]{audioEngine.setAmpMode(ampModeSelector.getSelectedId()==2?SignalChain::AmpMode::hq:SignalChain::AmpMode::legacy);};bypassButton.onClick=[this]{audioEngine.setBypass(bypassButton.getToggleState());};
    presetSelector.onChange=[this]{if(!refreshingPresets)loadSelectedPreset();};presetSaveButton.onClick=[this]{saveCurrentPreset();};presetDeleteButton.onClick=[this]{deleteSelectedPreset();};
    audioEngine.setInputGainDb(-6);audioEngine.setOutputGainDb(-18);audioEngine.setAmpMode(SignalChain::AmpMode::legacy);refreshPresetList();showPage(NavigationBar::Page::amp);startTimerHz(15);
}

MainView::~MainView(){stopTimer();}
juce::File MainView::getPresetDirectory()const{auto d=juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("GuitarDSP-Pro").getChildFile("Presets");d.createDirectory();return d;}
juce::File MainView::getPresetFile(const juce::String&n)const{auto s=n.trim().removeCharacters("\\/:*?\"<>|");if(s.isEmpty())s="Preset";return getPresetDirectory().getChildFile(s+".json");}
void MainView::refreshPresetList(const juce::String&p){refreshingPresets=true;auto keep=p.isNotEmpty()?p:presetSelector.getText();presetSelector.clear(juce::dontSendNotification);int id=1;for(const auto&f:getPresetDirectory().findChildFiles(juce::File::findFiles,false,"*.json"))presetSelector.addItem(f.getFileNameWithoutExtension(),id++);if(keep.isNotEmpty())presetSelector.setText(keep,juce::dontSendNotification);refreshingPresets=false;}

