    auto&rack=audioEngine.getHQEffectsRack();if(auto*a=r->getProperty("pedals").getArray())for(int i=0;i<juce::jmin((int)a->size(),guitardsp::hq::HQEffectsRack::pedalSlots);++i){auto*o=(*a)[i].getDynamicObject();auto&p=rack.pedalSlot(i);p.enabled.store(getBool(o,"enabled",p.enabled.load()));p.model.store(juce::jlimit(0,9,getInt(o,"model",p.model.load())));p.drive.store(getFloat(o,"drive",p.drive.load()));p.tone.store(getFloat(o,"tone",p.tone.load()));p.levelDb.store(getFloat(o,"level",p.levelDb.load()));p.mix.store(getFloat(o,"mix",p.mix.load()));p.aux1.store(getFloat(o,"aux1",p.aux1.load()));p.aux2.store(getFloat(o,"aux2",p.aux2.load()));p.aux3.store(getFloat(o,"aux3",p.aux3.load()));p.routeMask.store(juce::jlimit(0,7,getInt(o,"routeMask",p.routeMask.load())));}
    if(auto*o=r->getProperty("gate").getDynamicObject()){auto&g=rack.gateControl();rack.setDynamicsMode((guitardsp::hq::HQEffectsRack::DynamicsMode)juce::jlimit(0,3,getInt(o,"mode",(int)rack.getDynamicsMode())));g.thresholdDb.store(getFloat(o,"threshold",g.thresholdDb.load()));g.rangeDb.store(getFloat(o,"range",g.rangeDb.load()));g.ratio.store(getFloat(o,"ratio",g.ratio.load()));g.attackMs.store(getFloat(o,"attack",g.attackMs.load()));g.holdMs.store(getFloat(o,"hold",g.holdMs.load()));g.releaseMs.store(getFloat(o,"release",g.releaseMs.load()));g.hysteresisDb.store(getFloat(o,"hysteresis",g.hysteresisDb.load()));g.sidechainHpHz.store(getFloat(o,"hp",g.sidechainHpHz.load()));g.sidechainLpHz.store(getFloat(o,"lp",g.sidechainLpHz.load()));}
